def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit_values = {"Mercury": 1, "Venus": 2, "Earth": 3, "Mars": 4, "Jupiter": 5, "Saturn": 6, "Uranus": 7, "Neptune": 8}

    orbit1 = orbit_values[planet1]
    orbit2 = orbit_values[planet2]

    if orbit1 > orbit2:
        orbit1, orbit2 = orbit2, orbit1

    result = [planet for planet in planets if orbit1 < orbit_values[planet] < orbit2]

    return tuple(sorted(result, key=lambda x: orbit_values[x]))

